// -----------------------------------------------------------------------------
// HTTP client of the ARSO open data (meteo.arso.gov.si, no account, no key).
// Three kinds of XML files, all static and regenerated by ARSO:
//   - observationAms_si_latest.xml: the last reading of every automatic
//     station (10-minute pace), with its name and position;
//   - forecast_si_latest.xml (English): the daily forecast of the 15 regions;
//   - warning_SLOVENIA_<area>_latest_CAP.xml: the CAP 1.2 warnings of one of
//     the 5 warning areas, with the area polygon.
// Read-only GET requests, compressed (the observations weigh 800 KB raw,
// 30 KB gzipped). No query string: nothing personal ever leaves the house.
// -----------------------------------------------------------------------------

const BASE = 'https://meteo.arso.gov.si/uploads/probase/www';

/** The five warning areas of ARSO, as they appear in the file names. */
export const WARNING_AREAS = ['NORTH-WEST', 'SOUTH-WEST', 'MIDDLE', 'NORTH-EAST', 'SOUTH-EAST'];

export const URLS = {
  observations: `${BASE}/observ/surface/text/sl/observationAms_si_latest.xml`,
  forecast: `${BASE}/fproduct/text/en/forecast_si_latest.xml`,
  warnings: (area) => `${BASE}/warning/text/sl/warning_SLOVENIA_${area}_latest_CAP.xml`,
};

/** An answer that is not the expected XML: `status` is the HTTP status, if any. */
export class ArsoError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'ArsoError';
    this.status = status;
  }
}

/**
 * @param {object} [options]
 * @param {typeof fetch} [options.fetch]
 * @param {number} [options.timeoutMs]
 * @param {string} [options.userAgent]
 * @param {{ debug: Function }} [options.logger]
 */
export function createArsoClient({
  fetch = globalThis.fetch,
  timeoutMs = 20000,
  userAgent = 'gladys-arso (+https://github.com/guim31/gladys-arso)',
  logger,
} = {}) {
  async function getXml(address) {
    const url = new URL(address);
    const where = url.host + url.pathname;
    logger?.debug(`GET ${where}`);
    let response;
    try {
      response = await fetch(url, {
        headers: { accept: 'application/xml, text/xml', 'user-agent': userAgent },
        signal: AbortSignal.timeout(timeoutMs),
      });
    } catch (err) {
      const reason =
        err.name === 'TimeoutError' ? `no answer within ${timeoutMs / 1000} s` : err.message;
      throw new ArsoError(`${url.host} unreachable (${reason})`);
    }
    if (!response.ok) {
      throw new ArsoError(`${where} answered HTTP ${response.status}`, response.status);
    }
    const text = await response.text();
    if (!/^\s*(<\?xml[^>]*>\s*)?<(data|alert)[\s>]/.test(text)) {
      throw new ArsoError(`${where} answered something that is not ARSO XML`, response.status);
    }
    return text;
  }

  return {
    /** Last readings of every automatic station. */
    observations: () => getXml(URLS.observations),
    /** Daily forecast of every region, in English. */
    forecast: () => getXml(URLS.forecast),
    /** CAP warnings of one area (one of WARNING_AREAS). */
    warnings: (area) => getXml(URLS.warnings(area)),
  };
}
